actions.script:
const out = ec.service.sync().name('org.moqui.impl.DatabaseServices.cancel#DatabaseSession').parameters({db,
    pid: Number(context.pid), force: String(context.force) == 'true'}).call() || {}
forcePid = null
if (ec.message.hasError() && /set force/i.test(ec.message.errorsString) && String(context.force) != 'true') {
    ec.message.clearErrors()
    forcePid = String(context.pid)
    forceSignal = 'cancel'
} else if (!ec.message.hasError()) ec.message.addMessage(ec.l10n.localize(out.signalled ? 'The statement was cancelled' : 'The session was not found'), 'info')

const out = ec.service.sync().name('org.moqui.impl.DatabaseServices.terminate#DatabaseSession').parameters({db,
    pid: Number(context.pid), force: String(context.force) == 'true'}).call() || {}
forcePid = null
if (ec.message.hasError() && /set force/i.test(ec.message.errorsString) && String(context.force) != 'true') {
    ec.message.clearErrors()
    forcePid = String(context.pid)
    forceSignal = 'terminate'
} else if (!ec.message.hasError()) ec.message.addMessage(ec.l10n.localize(out.signalled ? 'The session was ended' : 'The session was not found'), 'info')

const call = (name) => {
    let out = null, error = null
    try { out = ec.service.sync().name('org.moqui.impl.DatabaseServices.' + name).parameters({db}).call() } catch (e) { error = String(e.message || e) }
    if (ec.message.hasError()) { error = ec.message.errorsString; ec.message.clearErrors() }
    return {out: out || {}, error}
}
const activity = call('get#DatabaseActivity')
activityError = activity.error
activityReasons = Object.entries(activity.out.reasons || {}).map(([part, reason]) => part + ': ' + reason)
instanceName = activity.out.instanceName || ''
const seconds = (ms) => ms == null ? '' : ms >= 60000 ? Math.round(ms / 60000) + ' min' : (ms / 1000).toFixed(1) + ' s'
sessionList = (activity.out.sessions || []).map((session) => ({pid: session.pid, user: session.user_name || '',
    application: session.application_name || session.client_addr || '', state: session.state || session.command || '',
    wait: [session.wait_event_type, session.wait_event].filter(Boolean).join(': '),
    running: session.query_ms != null ? seconds(session.query_ms) : session.time_seconds != null ? session.time_seconds + ' s' : '',
    transaction: seconds(session.xact_ms), query: session.query || '', blockedBy: session.blocked_by || '',
    marks: [session.own_app ? 'this server' : '', session.idle_in_transaction_long ? 'idle in transaction' : '',
        session.running_long ? 'running long' : '', session.is_self ? 'this page' : ''].filter(Boolean).join(', '),
    ownApp: !!session.own_app, isSelf: !!session.is_self}))
// the blocking chains as rows of a tree: a session that waits on no one, then those it blocks
blockingRows = []
const walk = (node, depth) => {
    const session = sessionList.find((item) => String(item.pid) == String(node.pid))
    blockingRows.push({indent: '    '.repeat(depth) + (depth ? '└ ' : ''), pid: node.pid,
        text: session ? [session.user, session.state, session.query.substring(0, 160)].filter(Boolean).join(' · ') : ''})
    for (const child of node.blocks || []) walk(child, depth + 1)
}
for (const chain of activity.out.blockingChains || []) walk(chain, 0)
canAdmin = ec.user.hasPermission('DATABASE_ADMIN')

const health = call('get#IndexHealth')
healthError = health.error
const h = health.out
healthRows = []
const add = (check, rows, name, detail) => { for (const row of rows || []) healthRows.push({check, table: row.table_name || '',
    name: name(row), detail: detail(row)}) }
add('Foreign key with no index', h.unindexedForeignKeys, (row) => row.constraint_name || '', (row) => [].concat(row.columns || []).join(', '))
add('Unused index', h.unusedIndexes, (row) => row.index_name || '', (row) => row.index_bytes != null ? ec.l10n.format(Number(row.index_bytes) / 1048576, '#,##0.0') + ' MiB' : '')
add('Duplicate index', h.duplicateIndexes, (row) => row.index_name || '', (row) => row.covered_by ? 'led by ' + row.covered_by : '')
add('Invalid index', h.invalidIndexes, (row) => row.index_name || '', () => 'a failed online build: drop it or build it again')
add('Transaction id age', h.databaseAge, (row) => row.database_name || 'database', (row) => row.xid_age != null ? ec.l10n.format(Number(row.xid_age), '#,##0') + ' of ' + ec.l10n.format(Number(row.freeze_max_age || 200000000), '#,##0') : '')
add('Table transaction id age', (h.tableAge || []).slice(0, 10), (row) => row.table_name || '', (row) => row.xid_age != null ? ec.l10n.format(Number(row.xid_age), '#,##0') : '')
healthReasons = Object.entries(h.reasons || {}).map(([part, reason]) => part + ': ' + reason)
statsSinceText = h.statsSince && Object.values(h.statsSince).find(Boolean) ? String(Object.values(h.statsSince).find(Boolean)) : ''
